ALTER TABLE bank_accounts ADD COLUMN halala INTEGER NOT NULL DEFAULT 0 CHECK(halala BETWEEN 0 AND 99);
CREATE TABLE IF NOT EXISTS telecom_purchases(id TEXT PRIMARY KEY,line_id TEXT NOT NULL REFERENCES telecom_lines(id),account_id TEXT NOT NULL REFERENCES bank_accounts(id),plan TEXT NOT NULL,amount_halala INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS telecom_usage(id TEXT PRIMARY KEY,line_id TEXT NOT NULL REFERENCES telecom_lines(id),kind TEXT NOT NULL,units INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
